#include <stdio.h>

void build(const char *letters, char *current, int used[], int depth, int n) {
    if (depth == n) {
        current[n] = '\0';
        printf("%s\n", current);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = 1;
            current[depth] = letters[i];
            build(letters, current, used, depth + 1, n);
            used[i] = 0;
        }
    }
}

int main() {
    char current[10];
    int used[3] = {0};
    build("abc", current, used, 0, 3);
    return 0;
}
